1	using System.Globalization;
2	using OrderOps.Api.Features.Events;
3	using OrderOps.Api.Infrastructure;
4	
5	namespace OrderOps.Api.Features.Orders;
6	
7	public sealed class OrdersService
8	{
9	    private readonly IOrderRepository _repo;
10	    private readonly IEventHub _events;
11	    private readonly ILogger<OrdersService> _log;
12	
13	    public OrdersService(IOrderRepository repo, IEventHub events, ILogger<OrdersService> log)
14	    {
15	        _repo = repo;
16	        _events = events;
17	        _log = log;
18	    }
19	
20	    public Task<PagedResult<OrderListItem>> ListAsync(OrderListRequest req, CancellationToken ct)
21	    {
22	        var (limit, offset) = Pagination.Normalize(req.Limit, req.Offset);
23	        var query = new OrderListQuery(
24	            ParseStatuses(req.Status),
25	            Trim(req.Priority),
26	            Trim(req.SupplierId),
27	            Trim(req.Warehouse),
28	            ParseDate(req.DateFrom, "date_from"),
29	            ParseDate(req.DateTo, "date_to"),
30	            req.MinTotal,
31	            Trim(req.Search),
32	            Trim(req.Sort),
33	            Trim(req.Order),
34	            limit,
35	            offset);
36	        return _repo.ListAsync(query, ct);
37	    }
38	
39	    public async Task<OrderDetail> GetByIdAsync(string id, CancellationToken ct)
40	    {
41	        var order = await _repo.GetByIdAsync(id, ct);
42	        if (order is null) throw new NotFoundException("Order");
43	        return order;
44	    }
45	
46	    public Task<OrderStats> GetStatsAsync(CancellationToken ct) => _repo.GetStatsAsync(ct);
47	
48	    public async Task<AnomalyResponse> GetAnomaliesAsync(CancellationToken ct)
49	    {
50	        var rows = await _repo.GetAnomalousAsync(ct);
51	        var items = new List<AnomalyItem>(rows.Count);
52	        foreach (var r in rows)
53	            items.Add(new AnomalyItem(r.OrderId, r.AnomalyTypes, DetermineSeverity(r.AnomalyTypes)));
54	        return new AnomalyResponse(items);
55	    }
56	
57	    private static readonly HashSet<string> HighSingle = new() { "negative_quantity", "price_mismatch", "timestamp_anomaly" };
58	    private static readonly HashSet<string> MediumSingle = new() { "inactive_supplier", "price_spike" };
59	
60	    private static string DetermineSeverity(string[] types)
61	    {
62	        if (types.Length >= 3) return "high";
63	        foreach (var t in types) if (t == "risky_supplier") return "high";
64	        foreach (var t in types) if (HighSingle.Contains(t)) return "high";
65	        if (types.Length == 2) return "medium";
66	        foreach (var t in types) if (MediumSingle.Contains(t)) return "medium";
67	        return "low";
68	    }
69	
70	    private const int MaxNotesLength = 4096;
71	
72	    public async Task<OrderDetail> UpdateStatusAsync(string id, PatchOrderRequest body, CancellationToken ct)
73	    {
74	        var status   = Trim(body.Status);
75	        var priority = Trim(body.Priority);
76	        var notes    = body.Notes; // notes preserved verbatim; only length-capped
77	
78	        if (status is null && priority is null && notes is null)
79	            throw new ValidationException("at least one of status, priority, notes is required", "no_fields");
80	
81	        if (status is not null && !OrderStatuses.IsValid(status))
82	            throw new ValidationException($"Invalid status '{status}'", "invalid_status");
83	        if (priority is not null && !OrderPriorities.IsValid(priority))
84	            throw new ValidationException($"Invalid priority '{priority}'", "invalid_priority");
85	        if (notes is not null && notes.Length > MaxNotesLength)
86	            throw new ValidationException($"notes exceeds {MaxNotesLength} characters", "notes_too_long");
87	
88	        var outcome = await _repo.UpdateAsync(id, new OrderUpdate(status, priority, notes), ct);
89	        switch (outcome)
90	        {
91	            case UpdateStatusOutcome.Updated u:
92	                if (!string.Equals(u.OldStatus, u.Order.Status, StringComparison.Ordinal))
93	                {
94	                    try
95	                    {
96	                        await _events.PublishAsync(new EventEnvelope(
97	                            "order_updated",
98	                            new OrderUpdatedPayload(u.Order.Id, u.OldStatus, u.Order.Status, u.Order.UpdatedAt),
99	                            u.Order.SupplierId));
100	                    }
101	                    catch (Exception ex)
102	                    {
103	                        _log.LogError(ex, "Failed to publish order_updated for {OrderId}", u.Order.Id);
104	                    }
105	                }
106	                return u.Order;
107	            case UpdateStatusOutcome.NotFound: throw new NotFoundException("Order");
108	            case UpdateStatusOutcome.AlreadyCancelled: throw new OrderAlreadyCancelledException();
109	            case UpdateStatusOutcome.VersionConflict: throw new OptimisticConcurrencyException();
110	            default: throw new InvalidOperationException("Unknown outcome");
111	        }
112	    }
113	
114	    private static string? Trim(string? s) => string.IsNullOrWhiteSpace(s) ? null : s.Trim();
115	
116	    private static IReadOnlyList<string>? ParseStatuses(string? raw)
117	    {
118	        if (string.IsNullOrWhiteSpace(raw)) return null;
119	        var parts = raw.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
120	        return parts.Length == 0 ? null : parts;
121	    }
122	
123	    private static DateTime? ParseDate(string? raw, string field)
124	    {
125	        if (string.IsNullOrWhiteSpace(raw)) return null;
126	        const DateTimeStyles styles = DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal;
127	        if (DateTime.TryParse(raw, CultureInfo.InvariantCulture, styles, out var d))
128	            return d;
129	        throw new ValidationException($"Invalid {field}: '{raw}'", "invalid_date");
130	    }
131	}
