202	                     CASE WHEN s.active = false                                        THEN 'inactive_supplier' END,
203	                     CASE WHEN o.unit_price > p.price * 1.5                            THEN 'price_spike' END,
204	                     CASE WHEN extract(hour FROM o.created_at) < 8
