5	namespace OrderOps.Api.Features.Suppliers;
6	
7	public sealed class SupplierRepository : ISupplierRepository
8	{
9	    private readonly AppDbContext _db;
10	
11	    public SupplierRepository(AppDbContext db) => _db = db;
12	
13	    public async Task<PagedResult<SupplierListItem>> ListAsync(int limit, int offset, CancellationToken ct)
14	    {
15	        var total = await _db.Suppliers.CountAsync(ct);
16	
17	        var rows = await _db.Suppliers.AsNoTracking()
18	            .OrderBy(s => s.Id)
19	            .Skip(offset).Take(limit)
20	            .Select(s => new SupplierListItem(
21	                s.Id, s.Name, s.Email, s.Rating, s.Country, s.Active, s.CreatedAt))
22	            .ToListAsync(ct);
23	
24	        return new PagedResult<SupplierListItem>(rows, total, limit, offset);
25	    }
26	
27	    public async Task<SupplierDetail?> GetByIdAsync(string id, CancellationToken ct)
28	    {
29	        return await _db.Suppliers.AsNoTracking()
30	            .Where(s => s.Id == id)
31	            .Select(s => new SupplierDetail(
32	                s.Id, s.Name, s.Email, s.Rating, s.Country, s.Active, s.CreatedAt,
33	                s.Orders.Count(),
34	                s.Orders.Sum(o => (decimal?)o.TotalPrice) ?? 0m))
35	            .FirstOrDefaultAsync(ct);
36	    }
37	
38	    private static readonly DateTime SeedRangeStart = new(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc);
39	    private static readonly int SeedMonthCount = 24;
40	
41	    public async Task<SupplierPerformance?> GetPerformanceAsync(string id, CancellationToken ct)
42	    {
43	        var exists = await _db.Suppliers.AsNoTracking().AnyAsync(s => s.Id == id, ct);
44	        if (!exists) return null;
45	
46	        var supplierOrders = _db.Orders.AsNoTracking().Where(o => o.SupplierId == id);
47	
48	        var totalOrders = await supplierOrders.LongCountAsync(ct);
49	
50	        double avgDeliveryDays = 0;
51	        if (totalOrders > 0)
52	        {
53	            var deliveredTimes = await supplierOrders
54	                .Where(o => o.Status == "delivered")
55	                .Select(o => new { o.CreatedAt, o.UpdatedAt })
56	                .ToListAsync(ct);
57	            if (deliveredTimes.Count > 0)
58	                avgDeliveryDays = deliveredTimes.Average(t => (t.UpdatedAt - t.CreatedAt).TotalDays);
59	        }
60	
61	        double rejectionRate = 0;
62	        if (totalOrders > 0)
63	        {
64	            var rejectedCount = await supplierOrders.Where(o => o.Status == "rejected").LongCountAsync(ct);
65	            rejectionRate = (double)rejectedCount / totalOrders;
66	        }
67	
68	        decimal avgOrderValue = 0;
69	        if (totalOrders > 0)
70	        {
71	            avgOrderValue = await supplierOrders.AverageAsync(o => o.TotalPrice, ct);
72	        }
73	
74	        var monthlyRaw = await supplierOrders
75	            .GroupBy(o => new { o.CreatedAt.Year, o.CreatedAt.Month })
76	            .Select(g => new { g.Key.Year, g.Key.Month, Count = g.LongCount(), Revenue = g.Sum(o => (decimal?)o.TotalPrice) ?? 0m })
77	            .ToListAsync(ct);
78	
79	        var monthlyByKey = monthlyRaw.ToDictionary(
80	            r => $"{r.Year:D4}-{r.Month:D2}",
81	            r => new MonthlyTrendEntry($"{r.Year:D4}-{r.Month:D2}", r.Count, r.Revenue));
82	
83	        var monthly = new List<MonthlyTrendEntry>(SeedMonthCount);
84	        for (int i = 0; i < SeedMonthCount; i++)
85	        {
86	            var d = SeedRangeStart.AddMonths(i);
87	            var key = $"{d.Year:D4}-{d.Month:D2}";
88	            monthly.Add(monthlyByKey.TryGetValue(key, out var entry)
89	                ? entry
90	                : new MonthlyTrendEntry(key, 0, 0m));
91	        }
92	
93	        double priceConsistency = 0;
94	        if (totalOrders > 0)
95	        {
96	            var consistencyRaw = await (
97	                from o in _db.Orders
98	                join p in _db.Products on o.ProductId equals p.Id
99	                where o.SupplierId == id
100	                select new { o.UnitPrice, p.Price })
101	                .ToListAsync(ct);
102	
103	            if (consistencyRaw.Count > 0)
104	            {
105	                var within = consistencyRaw.Count(x =>
106	                    x.Price > 0 && x.UnitPrice >= x.Price * 0.8m && x.UnitPrice <= x.Price * 1.2m);
107	                priceConsistency = (double)within / consistencyRaw.Count;
108	            }
109	        }
110	
111	        return new SupplierPerformance(
112	            id,
113	            totalOrders,
114	            Math.Round(avgDeliveryDays, 2),
115	            Math.Round(rejectionRate, 4),
116	            decimal.Round(avgOrderValue, 2),
117	            monthly,
118	            Math.Round(priceConsistency, 4));
119	    }
120	}
