2	using Npgsql;
3	using NpgsqlTypes;
4	using OrderOps.Api.Data;
5	using OrderOps.Api.Data.Entities;
6	
7	namespace OrderOps.Api.Features.Bulk;
8	
9	public sealed class BulkRepository : IBulkRepository
10	{
11	    private readonly AppDbContext _db;
12	
13	    public BulkRepository(AppDbContext db) => _db = db;
14	
15	    public async Task InsertJobAsync(string id, string action, int total, CancellationToken ct)
16	    {
17	        _db.Jobs.Add(new Job
18	        {
19	            Id = id,
20	            Status = "processing",
21	            Total = total,
22	            Completed = 0,
23	            Failed = 0,
24	            Action = action,
25	            CreatedAt = DateTime.UtcNow,
26	        });
27	        await _db.SaveChangesAsync(ct);
28	    }
29	
30	    public async Task<JobMirrorRow?> GetJobAsync(string id, CancellationToken ct)
31	    {
32	        var job = await _db.Jobs.AsNoTracking()
33	            .FirstOrDefaultAsync(j => j.Id == id, ct);
34	        if (job is null) return null;
35	
36	        return new JobMirrorRow
37	        {
38	            Id = job.Id,
39	            Status = job.Status,
40	            Total = job.Total,
41	            Completed = job.Completed,
42	            Failed = job.Failed,
43	            Action = job.Action,
44	        };
45	    }
46	
47	    public async Task FinalizeJobAsync(string id, string status, int completed, int failed, CancellationToken ct)
48	    {
49	        var job = await _db.Jobs.FirstOrDefaultAsync(j => j.Id == id, ct);
50	        if (job is null) return;
51	        job.Status = status;
52	        job.Completed = completed;
53	        job.Failed = failed;
54	        job.FinishedAt = DateTime.UtcNow;
55	        await _db.SaveChangesAsync(ct);
56	    }
57	
58	    private sealed class LockedRow
59	    {
60	        public string id { get; set; } = "";
61	        public string status { get; set; } = "";
62	        public int version { get; set; }
63	    }
64	
65	    public async Task<BulkChunkResult> ApplyChunkAsync(
66	        string jobId, string action, string? reason, string[] ids, CancellationToken ct)
67	    {
68	        if (ids.Length == 0) return new BulkChunkResult(0, 0);
69	
70	        var existing = await _db.Orders.AsNoTracking()
71	            .Where(o => ids.Contains(o.Id))
72	            .Select(o => o.Id)
73	            .ToListAsync(ct);
74	        var existingSet = existing.ToHashSet(StringComparer.Ordinal);
75	        var nonexistent = ids.Length - existingSet.Count;
76	
77	        await using var tx = await _db.Database.BeginTransactionAsync(ct);
78	
79	        var idsParam = new NpgsqlParameter("ids", NpgsqlDbType.Array | NpgsqlDbType.Text) { Value = ids };
80	        var locked = await _db.Database
81	            .SqlQueryRaw<LockedRow>(
82	                "SELECT id, status, version FROM orders WHERE id = ANY({0}) FOR UPDATE SKIP LOCKED",
83	                idsParam)
84	            .ToListAsync(ct);
85	
86	        var lockedIds = locked.Select(r => r.id).ToHashSet(StringComparer.Ordinal);
87	        var overlapCount = existingSet.Count(id => !lockedIds.Contains(id));
88	
89	        var completed = overlapCount;
90	        var failed = nonexistent;
91	
92	        if (action == BulkActions.Flag)
93	        {
94	            const string insertFlag =
95	                "INSERT INTO order_flags (order_id, source_job_id, reason) " +
96	                "VALUES (@order_id, @source_job_id, @reason) " +
97	                "ON CONFLICT (order_id) DO NOTHING";
98	
99	            foreach (var row in locked)
100	            {
101	                if (row.status == "cancelled") { failed++; continue; }
102	                await _db.Database.ExecuteSqlRawAsync(insertFlag, new[]
103	                {
104	                    new NpgsqlParameter("order_id", NpgsqlDbType.Varchar) { Value = row.id },
105	                    new NpgsqlParameter("source_job_id", NpgsqlDbType.Varchar) { Value = jobId },
106	                    new NpgsqlParameter("reason", NpgsqlDbType.Text) { Value = (object?)reason ?? DBNull.Value },
107	                }, ct);
108	                completed++;
109	            }
110	        }
111	        else
112	        {
113	            var newStatus = BulkActions.MapToStatus(action)
