3	
4	namespace OrderOps.Api.Features.Events;
5	
6	public sealed class EventHub : IEventHub, IAsyncDisposable
7	{
8	    private const int SubscriberChannelCapacity = 256;
9	    private const string BulkCompletedType = "bulk_completed";
10	
11	    private readonly ConcurrentDictionary<Guid, Subscriber> _subscribers = new();
12	    private readonly ILogger<EventHub> _log;
13	
14	    public EventHub(ILogger<EventHub> log) => _log = log;
15	
16	    public Guid Subscribe(string? supplierFilter, out ChannelReader<EventEnvelope> reader)
17	    {
18	        var channel = Channel.CreateBounded<EventEnvelope>(new BoundedChannelOptions(SubscriberChannelCapacity)
19	        {
20	            FullMode = BoundedChannelFullMode.DropOldest,
21	            SingleReader = true,
22	            SingleWriter = false,
23	        });
24	
25	        var id = Guid.NewGuid();
