1	using System.Diagnostics;
2	using System.Globalization;
3	using CsvHelper;
4	using CsvHelper.Configuration;
5	using CsvHelper.Configuration.Attributes;
6	using Microsoft.Extensions.Configuration;
7	using Microsoft.Extensions.Hosting;
8	using Npgsql;
9	using NpgsqlTypes;
10	
11	var builder = Host.CreateApplicationBuilder(new HostApplicationBuilderSettings
12	{
13	    Args = args,
14	    ContentRootPath = AppContext.BaseDirectory
15	});
16	var connStr = builder.Configuration.GetConnectionString("Postgres")
17	              ?? throw new InvalidOperationException("ConnectionStrings:Postgres is not configured.");
18	
19	var dataDir = ResolveDataDir();
20	var schemaPath = Path.Combine(AppContext.BaseDirectory, "schema.sql");
21	
22	Console.WriteLine($"[importer] data dir : {dataDir}");
23	Console.WriteLine($"[importer] schema   : {schemaPath}");
24	
25	var sw = Stopwatch.StartNew();
26	
27	await using var conn = new NpgsqlConnection(connStr);
28	await conn.OpenAsync();
29	Console.WriteLine($"[importer] connected to {conn.Host}:{conn.Port}/{conn.Database}");
30	
31	await ApplySchemaAsync(conn, schemaPath);
32	Console.WriteLine("[importer] schema applied");
33	
34	var categories = ReadCsv<CategoryRow>(Path.Combine(dataDir, "categories.csv"));
35	var suppliers  = ReadCsv<SupplierRow>(Path.Combine(dataDir, "suppliers.csv"));
36	var products   = ReadCsv<ProductRow>(Path.Combine(dataDir, "products.csv"));
37	var orders     = ReadCsv<OrderRow>(Path.Combine(dataDir, "orders.csv"));
38	Console.WriteLine($"[importer] parsed   : {categories.Count} cat, {suppliers.Count} sup, {products.Count} prod, {orders.Count} ord");
39	
40	// Reject orphan product → category references at parse time. The seed has 81 products
41	// pointing at cat_200, which doesn't exist in categories.csv. NULL-coerce those references
42	// so the FK stays enforced for genuine bugs and the DB never holds dangling pointers.
43	var categoryIds = categories.Select(c => c.Id).ToHashSet();
44	var orphanedProductCats = 0;
45	foreach (var p in products)
46	{
47	    if (!string.IsNullOrEmpty(p.CategoryId) && !categoryIds.Contains(p.CategoryId))
48	    {
49	        p.CategoryId = null;
50	        orphanedProductCats++;
51	    }
52	}
53	if (orphanedProductCats > 0)
54	    Console.WriteLine($"[importer] fixup   : NULL-coerced {orphanedProductCats} product category_id orphan(s)");
55	
56	await using (var tx = await conn.BeginTransactionAsync())
57	{
58	    await ExecAsync(conn, tx, "SET CONSTRAINTS ALL DEFERRED");
59	    await CopyCategoriesAsync(conn, categories);
60	    await CopySuppliersAsync(conn, suppliers);
61	    await CopyProductsAsync(conn, products);
62	    await CopyOrdersAsync(conn, orders);
63	    await tx.CommitAsync();
64	}
65	Console.WriteLine("[importer] COPY complete; FK constraints validated on commit");
66	
67	var ok = true;
68	ok &= await VerifyCountAsync(conn, "categories", categories.Count);
69	ok &= await VerifyCountAsync(conn, "suppliers",  suppliers.Count);
70	ok &= await VerifyCountAsync(conn, "products",   products.Count);
71	ok &= await VerifyCountAsync(conn, "orders",     orders.Count);
72	
73	sw.Stop();
74	if (!ok)
75	{
76	    Console.Error.WriteLine($"[importer] FAILED — count mismatch (elapsed {sw.Elapsed.TotalSeconds:F2}s)");
77	    return 1;
78	}
79	Console.WriteLine($"[importer] OK ({sw.Elapsed.TotalSeconds:F2}s)");
80	return 0;
81	
82	static string ResolveDataDir()
83	{
84	    var dir = Directory.GetCurrentDirectory();
85	    while (!string.IsNullOrEmpty(dir))
86	    {
87	        var candidate = Path.Combine(dir, "data");
88	        if (File.Exists(Path.Combine(candidate, "orders.csv")))
89	            return candidate;
90	        dir = Path.GetDirectoryName(dir);
91	    }
92	    throw new DirectoryNotFoundException(
93	        "Could not locate /data by walking up from " + Directory.GetCurrentDirectory());
94	}
95	
96	static async Task ApplySchemaAsync(NpgsqlConnection conn, string path)
97	{
98	    var sql = await File.ReadAllTextAsync(path);
99	    await using var cmd = new NpgsqlCommand(sql, conn);
100	    await cmd.ExecuteNonQueryAsync();
101	}
102	
103	static async Task ExecAsync(NpgsqlConnection conn, NpgsqlTransaction tx, string sql)
104	{
105	    await using var cmd = new NpgsqlCommand(sql, conn, tx);
106	    await cmd.ExecuteNonQueryAsync();
107	}
108	
109	static List<T> ReadCsv<T>(string path)
110	{
111	    using var reader = new StreamReader(path);
112	    var cfg = new CsvConfiguration(CultureInfo.InvariantCulture) { HasHeaderRecord = true };
113	    using var csv = new CsvReader(reader, cfg);
114	    return csv.GetRecords<T>().ToList();
115	}
116	
117	static string? Nz(string? s) => string.IsNullOrEmpty(s) ? null : s;
118	
119	static async Task CopyCategoriesAsync(NpgsqlConnection conn, List<CategoryRow> rows)
120	{
121	    await using var w = await conn.BeginBinaryImportAsync(
122	        "COPY categories (id, name, parent_id) FROM STDIN (FORMAT BINARY)");
123	    foreach (var r in rows)
124	    {
125	        await w.StartRowAsync();
126	        await w.WriteAsync(r.Id, NpgsqlDbType.Varchar);
127	        await w.WriteAsync(r.Name, NpgsqlDbType.Text);
128	        var p = Nz(r.ParentId);
129	        if (p is null) await w.WriteNullAsync();
130	        else           await w.WriteAsync(p, NpgsqlDbType.Varchar);
131	    }
132	    await w.CompleteAsync();
133	}
134	
135	static async Task CopySuppliersAsync(NpgsqlConnection conn, List<SupplierRow> rows)
136	{
137	    await using var w = await conn.BeginBinaryImportAsync(
138	        "COPY suppliers (id, name, email, rating, country, active, created_at) FROM STDIN (FORMAT BINARY)");
139	    foreach (var r in rows)
140	    {
141	        await w.StartRowAsync();
142	        await w.WriteAsync(r.Id, NpgsqlDbType.Varchar);
143	        await w.WriteAsync(r.Name, NpgsqlDbType.Text);
144	
145	        var email = Nz(r.Email);
146	        if (email is null) await w.WriteNullAsync(); else await w.WriteAsync(email, NpgsqlDbType.Text);
147	
148	        if (r.Rating is null) await w.WriteNullAsync(); else await w.WriteAsync(r.Rating.Value, NpgsqlDbType.Numeric);
149	
150	        var country = Nz(r.Country);
151	        if (country is null) await w.WriteNullAsync(); else await w.WriteAsync(country, NpgsqlDbType.Varchar);
152	
153	        await w.WriteAsync(r.Active, NpgsqlDbType.Boolean);
154	        await w.WriteAsync(r.CreatedAt, NpgsqlDbType.TimestampTz);
155	    }
156	    await w.CompleteAsync();
157	}
158	
159	static async Task CopyProductsAsync(NpgsqlConnection conn, List<ProductRow> rows)
160	{
161	    await using var w = await conn.BeginBinaryImportAsync(
162	        "COPY products (id, name, category_id, sku, price) FROM STDIN (FORMAT BINARY)");
163	    foreach (var r in rows)
164	    {
165	        await w.StartRowAsync();
166	        await w.WriteAsync(r.Id, NpgsqlDbType.Varchar);
167	        await w.WriteAsync(r.Name, NpgsqlDbType.Text);
168	
169	        var cat = Nz(r.CategoryId);
170	        if (cat is null) await w.WriteNullAsync(); else await w.WriteAsync(cat, NpgsqlDbType.Varchar);
171	
172	        var sku = Nz(r.Sku);
173	        if (sku is null) await w.WriteNullAsync(); else await w.WriteAsync(sku, NpgsqlDbType.Text);
174	
175	        await w.WriteAsync(r.Price, NpgsqlDbType.Numeric);
176	    }
177	    await w.CompleteAsync();
178	}
179	
180	static async Task CopyOrdersAsync(NpgsqlConnection conn, List<OrderRow> rows)
181	{
182	    await using var w = await conn.BeginBinaryImportAsync(
183	        "COPY orders (id, supplier_id, product_id, quantity, unit_price, total_price, status, priority, created_at, updated_at, warehouse, notes, version) FROM STDIN (FORMAT BINARY)");
184	    foreach (var r in rows)
185	    {
186	        await w.StartRowAsync();
187	        await w.WriteAsync(r.Id,         NpgsqlDbType.Varchar);
188	        await w.WriteAsync(r.SupplierId, NpgsqlDbType.Varchar);
